import{_ as t,o,c as d,a0 as s}from"./chunks/framework.C3yZ6M33.js";const p=JSON.parse('{"title":"Scope resolution","description":"","frontmatter":{},"headers":[],"relativePath":"reference/scope-resolution.md","filePath":"reference/scope-resolution.md"}'),c={name:"reference/scope-resolution.md"};function a(r,e,n,i,l,h){return o(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="scope-resolution" tabindex="-1">Scope resolution <a class="header-anchor" href="#scope-resolution" aria-label="Permalink to &quot;Scope resolution&quot;">​</a></h1><p><code>${event.*}</code>, <code>${config.*}</code>, <code>${params.*}</code>, <code>${state.*}</code>, <code>${node.*}</code>, <code>${secret.*}</code> — the scope-resolution pass. This contract is net-new: v1 never had it (its tests assert <code>${config.region}</code> passes through literally), and the ported <code>libraries/</code> artifacts are dead without it. It specifies <em>what</em> the pass resolves and <em>where</em> it sits so any later phase can implement it without re-deriving semantics.</p><h2 id="position-in-the-pipeline" tabindex="-1">Position in the pipeline <a class="header-anchor" href="#position-in-the-pipeline" aria-label="Permalink to &quot;Position in the pipeline&quot;">​</a></h2><p><code>resolve_template</code> (peregrin-template) resolves a string in four stages. The scope pass is stage 3:</p><ol><li><strong>Default normalization</strong> (<code>resolve_defaults</code>) — rewrites <code>${x :- d}</code> to canonical <code>${x:-d}</code>, recursing into defaults. Text-only; resolves nothing.</li><li><strong>Function resolution</strong> (<code>render_template</code>) — scans <code>${</code>…<code>}</code> (up to the first <code>}</code>, non-empty interior); <code>${name(args)}</code> / <code>${name.method(args)}</code> with a known <em>and granted</em> function resolves; every other placeholder is emitted verbatim. Function calls are fully consumed here — the scope pass never sees them.</li><li><strong>Scope resolution</strong> <em>(this spec)</em> — re-scans the rendered text and resolves scope-namespaced placeholders. Misses stay verbatim.</li><li><strong>Strict audit</strong> — under <code>strict: true</code>, any remaining <code>${...}</code> that isn&#39;t a granted function call fails with <code>unresolved placeholders: …</code>; a non-empty missing-secrets ledger fails with <code>missing secrets: …</code>.</li></ol><p>Stage 3 must run <em>after</em> function resolution (functions win ambiguous syntax) and <em>before</em> the strict audit (a failed scope lookup must be visible to the audit). In lenient mode the audit doesn&#39;t run and every unresolved placeholder passes through verbatim — the existing doctrine, unchanged.</p><h2 id="grammar" tabindex="-1">Grammar <a class="header-anchor" href="#grammar" aria-label="Permalink to &quot;Grammar&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>placeholder  := &quot;${&quot; scope-expr &quot;}&quot;</span></span>\n<span class="line"><span>scope-expr   := ns ( &quot;.&quot; segment )+ ( &quot;:-&quot; default )?</span></span>\n<span class="line"><span>ns           := &quot;event&quot; | &quot;config&quot; | &quot;params&quot; | &quot;state&quot; | &quot;node&quot; | &quot;secret&quot;</span></span></code></pre></div><ul><li><code>segment</code> is any non-empty run between <code>.</code> separators — dotted paths walk nested objects one key per segment. A path that needs a key containing <code>.</code> is unreachable by design (name keys to avoid it).</li><li>A bare <code>${ns}</code> with no path is <strong>unresolved</strong> (no meaningful string form) — except <code>${event.match.N}</code>/<code>${event.shard}</code> style paths, which are normal segments.</li><li><code>secret</code> is the exception: <code>${secret.NAME}</code> treats everything up to <code>:-</code> or <code>}</code> as a single key, so secret names may contain dots.</li><li>Anything that parsed as a function call in stage 2 — or uses <code>|</code> filters — is not a scope expression and is left alone.</li><li>Resolved values stringify via <code>toStringSafe</code>: <code>null</code> → <code>&quot;&quot;</code>, booleans/numbers as JS <code>String(v)</code>, arrays join with <code>,</code> (null elements → <code>&quot;&quot;</code>), objects → <code>[object Object]</code>.</li></ul><h2 id="namespaces" tabindex="-1">Namespaces <a class="header-anchor" href="#namespaces" aria-label="Permalink to &quot;Namespaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prefix</th><th>Bound to</th><th>Forms</th></tr></thead><tbody><tr><td><code>event</code></td><td><code>triggers[0]</code> of the current fire</td><td><code>type</code>, <code>id</code>, <code>ts</code>, <code>source</code>, <code>payload.&lt;path&gt;</code>, <code>match.&lt;N&gt;</code>, <code>shard</code></td></tr><tr><td><code>config</code></td><td>the campaign <code>config:</code> map</td><td><code>config.&lt;path&gt;</code></td></tr><tr><td><code>params</code></td><td>the node&#39;s <code>params:</code> — lazily resolved</td><td><code>params.&lt;path&gt;</code></td></tr><tr><td><code>state</code></td><td>the ctx state store (scoped store when <code>state.key</code> is set, else the shared run store)</td><td><code>state.&lt;key&gt;[.&lt;path&gt;]</code></td></tr><tr><td><code>node</code></td><td>the firing node</td><td><code>id</code>, <code>fires</code></td></tr><tr><td><code>secret</code></td><td>the run&#39;s secrets record, capability-gated</td><td><code>secret.&lt;name&gt;</code></td></tr></tbody></table><h3 id="event" tabindex="-1"><code>event</code> <a class="header-anchor" href="#event" aria-label="Permalink to &quot;`event`&quot;">​</a></h3><p><code>event</code> binds to the <strong>first trigger</strong> of the current fire — <code>triggers[0]</code> in the vector the bus produced (for <code>mode: all</code> that&#39;s the earliest <code>on</code> pattern&#39;s first match; for <code>fan_in</code> the oldest matching event; after <code>seed</code>/<code>check_ready</code> the first logged match). Multi-trigger nodes needing per-trigger data should read <code>fan_in</code>&#39;s payload or publish side events — <code>event</code> deliberately means &quot;the trigger&quot;.</p><ul><li><code>event.type</code>, <code>event.id</code>, <code>event.ts</code>, <code>event.source</code> — envelope fields of the bound event.</li><li><code>event.payload.&lt;path&gt;</code> — walks the payload object; a non-object step or missing key is a miss.</li><li><code>event.match.&lt;N&gt;</code> / <code>event.shard</code> — wildcard captures from the <strong>first <code>on</code> pattern that matched the bound trigger</strong> (<code>capture_wildcards</code>); <code>shard</code> aliases <code>match.1</code>. No wildcard or no matching pattern → miss.</li><li>When no trigger is bound (resolutions outside a fire — e.g. a driver re-resolving without one) every <code>event.*</code> lookup misses.</li></ul><h3 id="config" tabindex="-1"><code>config</code> <a class="header-anchor" href="#config" aria-label="Permalink to &quot;`config`&quot;">​</a></h3><p><code>config.&lt;path&gt;</code> walks the campaign <code>config:</code> map. Missing key or non-object step → miss.</p><h3 id="params" tabindex="-1"><code>params</code> <a class="header-anchor" href="#params" aria-label="Permalink to &quot;`params`&quot;">​</a></h3><p><code>params</code> resolves against the node&#39;s declared <code>params:</code> map with <strong>lazy memoization</strong>:</p><ul><li>During resolution of <code>node.params</code> itself, <code>params.&lt;path&gt;</code> resolves the referenced key through the full pipeline (defaults → functions → scope) on first reference and memoizes it for the rest of that resolution pass.</li><li>A circular reference — <code>a</code> referencing <code>params.a</code> directly or transitively — is a miss (the in-progress key is never visible).</li><li>Outside params resolution (<code>state.key</code>, <code>state.skip_if</code>, <code>ctx.emit</code> payloads, <code>forward</code> destinations, driver-side re-resolves), <code>params</code> binds the <strong>already-resolved</strong> params object produced for the fire.</li><li>Path walk: dict keys only; missing key or scalar step → miss.</li></ul><h3 id="state" tabindex="-1"><code>state</code> <a class="header-anchor" href="#state" aria-label="Permalink to &quot;`state`&quot;">​</a></h3><p><code>state.&lt;key&gt;</code> looks up <code>&lt;key&gt;</code> (the first path segment) in the ctx&#39;s state store — the scoped <code>state.key</code> store when the node declares one, else the shared run store — then walks remaining segments into the stored record. Absent key → miss. This gives nodes read access to their own record and to shared campaign state; writes stay on <code>ctx.state</code> in drivers.</p><h3 id="node" tabindex="-1"><code>node</code> <a class="header-anchor" href="#node" aria-label="Permalink to &quot;`node`&quot;">​</a></h3><p><code>node.id</code> (string) and <code>node.fires</code> (number — the fire count including the current fire). Unbound when the resolve call carries no node → miss.</p><h3 id="secret" tabindex="-1"><code>secret</code> <a class="header-anchor" href="#secret" aria-label="Permalink to &quot;`secret`&quot;">​</a></h3><p><code>${secret.NAME}</code> resolves through the same contract as <code>ctx.get_secret(NAME)</code>:</p><ol><li><strong>Gate</strong> — <code>capabilities.secrets</code> (the merged ctx capability map) must be present and not <code>false</code>; otherwise the placeholder is unresolved. (Mirrors the function gate: presence whitelists.)</li><li><strong>Match (strict only)</strong> — under <code>strict</code>, the grant must match <code>NAME</code>: <code>true</code> allows all, a list is name globs, <code>{allow, deny}</code> applies deny-then-allow. A non-matching grant fails with <code>capability &#39;secrets&#39; not granted for &#39;NAME&#39;</code> — the same error surface as <code>${env(...)}</code>/<code>${file(...)}</code>/<code>${shell(...)}</code> grants. Non-strict skips argument matching, like every other capability.</li><li><strong>Lookup</strong> — resolves through <code>ctx.resolve_secret</code>: the run&#39;s secrets record, then ambient process env, then the fallback stores (<code>secret_stores</code>; OS keyring — consulted only for grant-matched names — then <code>~/.config/peregrin/env</code>). A hit substitutes the value. <strong>Miss substitutes <code>&quot;&quot;</code></strong> and, under strict, records <code>NAME</code> in the missing-secrets ledger — the audit then fails with <code>missing secrets: NAME</code>.</li></ol><p>Ruling on the miss: substitute <code>&quot;&quot;</code>, not pass-through. It mirrors <code>ctx.get_secret</code>/<code>ctx.secrets[name]</code> exactly — one secrets contract, two access surfaces — and matches <code>${env(&quot;UNSET&quot;)}</code> → <code>&quot;&quot;</code>. A verbatim <code>${secret.NAME}</code> leaking into a resolved param would put placeholder text into driver inputs and would be <em>less</em> auditable than the ledger. Users wanting a fallback write <code>${secret.NAME:-fallback}</code>.</p><h2 id="misses-defaults-and-strict-mode" tabindex="-1">Misses, defaults, and strict mode <a class="header-anchor" href="#misses-defaults-and-strict-mode" aria-label="Permalink to &quot;Misses, defaults, and strict mode&quot;">​</a></h2><p>A <strong>miss</strong> is any failure to resolve: unknown namespace, missing key, unbound <code>event</code>/<code>node</code>, ungated <code>secret</code>, circular <code>params</code>, a scalar mid-path. Miss handling:</p><ul><li><code>${ns.path}</code> → the placeholder is emitted <strong>verbatim</strong>. In lenient mode that&#39;s the final result (pass-through doctrine). Under strict the stage-4 audit flags it — the audit&#39;s resolvable-looking set shrinks to granted function calls and the five I/O-builtin dotted forms (<code>env</code>, <code>file</code>, <code>shell</code>, <code>random</code>, <code>uuid</code>, <code>now</code>); leftover scope-namespace placeholders now count as unresolvable.</li><li><code>${ns.path:-default}</code> → the lookup miss substitutes <code>default</code> and the substituted text is re-resolved through the <strong>full pipeline</strong> (defaults normalization → functions → scope), so <code>${config.a:-${config.b}}</code> chains and <code>${config.a:-${env(&quot;FALLBACK&quot;)}}</code> both work. The depth of chained substitutions is capped (8); exceeding the cap treats the expression as a miss. A default is only consulted on a miss — <code>${config.a:-d}</code> with <code>a</code> present resolves to <code>a</code>, even when <code>a</code> is <code>&quot;&quot;</code> or <code>null</code> (which stringify to <code>&quot;&quot;</code> anyway). This is the first feature to actually consume <code>:-</code> defaults: stage 1 only ever normalized their text.</li></ul><h2 id="binding-summary-for-implementers" tabindex="-1">Binding summary for implementers <a class="header-anchor" href="#binding-summary-for-implementers" aria-label="Permalink to &quot;Binding summary for implementers&quot;">​</a></h2><p>The runner supplies scope bindings alongside the existing template <code>Context</code>/<code>Options</code> (<code>strict</code>, <code>missing_secrets</code>, <code>capabilities</code>, <code>effects</code>, <code>node</code>, <code>functions</code>):</p><table tabindex="0"><thead><tr><th>Binding</th><th>Source at a node fire</th></tr></thead><tbody><tr><td><code>event</code></td><td><code>triggers[0]</code> + the node&#39;s <code>on</code> patterns (for captures)</td></tr><tr><td><code>config</code></td><td><code>ctx.config</code> (campaign <code>config:</code>)</td></tr><tr><td><code>params</code></td><td>declared <code>node.params</code> during param resolution; resolved params afterwards</td></tr><tr><td><code>state</code></td><td><code>ctx.state</code> — scoped when <code>state.key</code> is declared, shared otherwise</td></tr><tr><td><code>node</code></td><td><code>node.id</code>, <code>ctx.fires</code></td></tr><tr><td><code>secret</code></td><td><code>ctx.secrets</code> gated by <code>capabilities.secrets</code></td></tr></tbody></table><p>All node-fire-time resolutions — <code>params</code>, <code>state.key</code>, <code>state.skip_if</code>, and driver-side re-resolves that receive a trigger — bind the same <code>event</code>. Resolutions with no fire context leave <code>event</code> and <code>node</code> unbound.</p>',34)])])}const m=t(c,[["render",a]]);export{p as __pageData,m as default};
